using System;
namespace UnityEngine {public static class Random {public static int Range(int min,int max){return min;}}}
class TypedDamageChecks {
static void Check(bool v,string text){if(!v)throw new Exception(text);}
static void Main(){var m=new MonsterDamage();m.Counts[0]=6;m.Types[0]=5;m.Counts[1]=4;m.Bonus=-8;string details;Check(m.Roll(out details)==6&&m.LastTypedDamage[5]==6&&m.LastTypedDamage[0]==0,"negative fixed only offsets its own type");m.Bonus=-3;Check(m.Roll(out details,true)==17&&m.LastTypedDamage[5]==12&&m.LastTypedDamage[0]==5,"critical doubles dice not fixed");var raw=new long[13];raw[5]=5;var r=new bool[13];r[5]=true;var v=new bool[13];v[5]=true;var immune=new bool[13];immune[5]=true;Check(DamageTypes.Resolve(raw,r)[5]==2,"resistance floor");Check(DamageTypes.Resolve(raw,r,null,v)[5]==4,"resistance before vulnerability");Check(DamageTypes.Resolve(raw,r,immune,v)[5]==0,"immunity overrides");raw[0]=-10;Check(DamageTypes.Total(DamageTypes.Resolve(raw))==5,"per-type clamp");raw[5]=long.MaxValue;Check(DamageTypes.Total(DamageTypes.Resolve(raw))==int.MaxValue,"saturated total");var c=new CombatState();c.PlayerEnergyResistance=5;var packet=new long[13];packet[5]=7;packet[0]=5;Check(c.AdjustPlayerPacket(packet)==8,"mixed packet resistance by type");Check(c.AdjustTypedDamage(false,7,5)==7,"unprotected other actor");c.MonsterEnergyResistance=5;Check(c.AdjustTypedDamage(false,7,5)==3,"monster energy resistance");c.PlayerArmorFloor=17;c.ActivateShield();Check(c.PlayerArmorClass==17,"barkskin floor applies after shield");c.SetPlayerArmorOverride(12);c.PlayerArmorBonus=2;Check(c.PlayerArmorClass==19,"barkskin does not override higher final armor");c.UpdateMonsterArmorClass(30);c.MonsterArmorBonus=2;Check(c.MonsterArmorClass==32,"buff above configured armor limit");c.PlayerBladeWard=true;c.ResetBattle();Check(!c.PlayerBladeWard&&c.PlayerEnergyResistance==-1&&c.MonsterEnergyResistance==-1&&c.PlayerArmorFloor==0&&c.PlayerArmorBonus==0,"reset clears defensive effects");Console.WriteLine("PASS: independent damage types, same-type negative bonus, critical fixed bonus, resistance rounding, vulnerability, immunity and overflow");}}
